let __v_4089 = pyrt::literals::decode("{\"$tuple\":[\"not working\",\"isnt working\",\"isn't working\",\"not heating\",\"not heating up\",\"wont heat\",\"won't heat\",\"wont heat up\",\"won't heat up\",\"not getting hot\",\"not hot\",\"cold\",\"cold water\",\"only cold\",\"lukewarm\",\"tepid\",\"stopped\",\"stopped working\",\"packed up\",\"broken\",\"fault\",\"faulty\",\"tripping\",\"trips\",\"trip\",\"fuse\",\"fuse box\",\"cut out\",\"cutting out\",\"reset\",\"test\",\"check\",\"fix\",\"mend\",\"repair\",\"replace\",\"element\",\"thermostat\"]}")?;
